const CURRENT_SEASON_SLUG = "spring-2026";
const SEASON_NAV_PREFIX = "../season/";
const THIS_SEASON_SLUG = "spring-2026";

// ── Season selector navigation ────────────────────────────────────
document.getElementById('season-select').addEventListener('change', function() {
  const slug = this.value;
  const dest = slug === CURRENT_SEASON_SLUG
    ? SEASON_NAV_PREFIX.replace(/season\/$/, '') + 'teams/'
    : SEASON_NAV_PREFIX + slug + '/teams/';
  window.location.href = dest;
});

// ── Search ────────────────────────────────────────────────────────
const searchEl    = document.getElementById('team-search');
const resultsEl   = document.getElementById('search-results');
const countEl     = document.getElementById('result-count');
const listEl      = document.getElementById('result-list');
const directoryEl = document.getElementById('directory');

function highlight(text, query) {
  if (!query) return text;
  const esc = query.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  return text.replace(new RegExp(`(${esc})`, 'gi'), '<mark>$1</mark>');
}

function doSearch(raw) {
  const q = raw.trim().toLowerCase();
  if (!q) {
    resultsEl.classList.remove('visible');
    directoryEl.style.display = '';
    return;
  }
  directoryEl.style.display = 'none';
  resultsEl.classList.add('visible');

  const matches = TEAMS.filter(t => t.name.toLowerCase().includes(q));
  countEl.textContent = matches.length
    ? `${matches.length} team${matches.length === 1 ? '' : 's'} found`
    : '';

  if (!matches.length) {
    listEl.innerHTML = `<div class="no-results">No teams match "<strong>${raw.trim()}</strong>"</div>`;
    return;
  }

  listEl.innerHTML = matches.map(t => `
    <a class="result-card" href="${FLIGHT_URL_PREFIX}${t.flight_slug}/" data-flight-slug="${t.flight_slug}">
      <div style="flex:1;min-width:0">
        <div class="result-name">${highlight(t.name, raw.trim())}</div>
        <div class="result-flight">${t.flight_label}</div>
      </div>
      <span class="result-arrow">→</span>
    </a>
  `).join('');
  bindFlightPreviewHover(listEl);
}

searchEl.addEventListener('input', () => doSearch(searchEl.value));
searchEl.focus();

const flightPopup = document.getElementById('flight-popup');
const flightPopupTitle = document.getElementById('flight-popup-title');
const flightPopupBody = document.getElementById('flight-popup-body');
let flightPopupTimer = null;

function hideFlightPopup() {
  if (flightPopupTimer) {
    clearTimeout(flightPopupTimer);
    flightPopupTimer = null;
  }
  flightPopup.classList.remove('visible');
}

function scheduleFlightPopup(link) {
  const slug = link.dataset.flightSlug;
  if (!slug) return;
  if (flightPopupTimer) clearTimeout(flightPopupTimer);
  flightPopupTimer = setTimeout(() => renderFlightPopup(link, slug), 800);
}

function renderFlightPopup(anchor, slug) {
  const preview = FLIGHT_PREVIEWS[slug];
  if (!preview) return;
  flightPopupTitle.textContent = preview.label;
  const standings = preview.standings || [];
  flightPopupBody.innerHTML = standings.map((row, idx) => `
    <div class="flight-popup-row">
      <div class="flight-popup-team">${idx + 1}. ${row.team}</div>
      <div class="flight-popup-metrics">${row.pts} pts · GD ${row.gd >= 0 ? '+' + row.gd : row.gd}</div>
    </div>
  `).join('');
  flightPopup.classList.add('visible');

  const rect = anchor.getBoundingClientRect();
  const pw = flightPopup.offsetWidth || 320;
  const ph = flightPopup.offsetHeight || 240;
  const gap = 12;
  let left = rect.right + gap;
  let top = rect.top;
  if (left + pw > window.innerWidth - 8) left = rect.left - pw - gap;
  if (top + ph > window.innerHeight - 8) top = window.innerHeight - ph - 8;
  if (top < 8) top = 8;
  flightPopup.style.left = `${left}px`;
  flightPopup.style.top = `${top}px`;
}

function bindFlightPreviewHover(scope = document) {
  scope.querySelectorAll('[data-flight-slug]').forEach(link => {
    if (link.dataset.previewBound === '1') return;
    link.dataset.previewBound = '1';
    link.addEventListener('pointerenter', () => scheduleFlightPopup(link));
    link.addEventListener('focus', () => scheduleFlightPopup(link));
    link.addEventListener('pointerleave', (e) => {
      if (flightPopup.contains(e.relatedTarget)) return;
      hideFlightPopup();
    });
    link.addEventListener('blur', hideFlightPopup);
  });
}

flightPopup.addEventListener('pointerenter', () => {
  if (flightPopupTimer) {
    clearTimeout(flightPopupTimer);
    flightPopupTimer = null;
  }
});
flightPopup.addEventListener('pointerleave', hideFlightPopup);

bindFlightPreviewHover();

document.querySelectorAll('[data-flight-slug]').forEach(link => {
  if (link.dataset.mousePreviewBound === '1') return;
  link.dataset.mousePreviewBound = '1';
  link.addEventListener('mouseenter', () => scheduleFlightPopup(link));
  link.addEventListener('mouseleave', (e) => {
    if (flightPopup.contains(e.relatedTarget)) return;
    hideFlightPopup();
  });
});

document.addEventListener('mouseover', (e) => {
  const link = e.target.closest('[data-flight-slug]');
  if (!link) return;
  scheduleFlightPopup(link);
});

document.addEventListener('mouseout', (e) => {
  const link = e.target.closest('[data-flight-slug]');
  if (!link) return;
  const next = e.relatedTarget;
  if (next && (link.contains(next) || flightPopup.contains(next))) return;
  hideFlightPopup();
});
